package com.ptit.poker.admin.api;

import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.ptit.poker.auth.domain.*;import com.ptit.poker.auth.infrastructure.persistence.*;import com.ptit.poker.auth.infrastructure.security.JwtService;import com.ptit.poker.game.domain.state.*;import com.ptit.poker.game.infrastructure.persistence.*;import com.ptit.poker.room.domain.*;import com.ptit.poker.room.infrastructure.persistence.*;import com.ptit.poker.support.TestDatabaseSafetyInitializer;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.HttpHeaders;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;import org.springframework.test.web.servlet.MockMvc;

@EnabledIfEnvironmentVariable(named="TEST_DB_URL",matches=".+") @EnabledIfEnvironmentVariable(named="TEST_DB_USERNAME",matches=".+") @EnabledIfEnvironmentVariable(named="TEST_DB_PASSWORD",matches=".+") @ActiveProfiles("test") @ContextConfiguration(initializers=TestDatabaseSafetyInitializer.class) @SpringBootTest @AutoConfigureMockMvc
class AdminApiMySqlIntegrationTests {
 @Autowired MockMvc mvc;@Autowired UserRepository users;@Autowired RoomRepository rooms;@Autowired RoomPlayerRepository roomPlayers;@Autowired GameSessionRepository sessions;@Autowired PokerHandRepository hands;@Autowired HandPlayerRepository handPlayers;@Autowired JwtService jwt;@Autowired JdbcTemplate jdbc;private final List<Long> userIds=new ArrayList<>(),roomIds=new ArrayList<>(),sessionIds=new ArrayList<>();
 @AfterEach void cleanup(){for(long id:sessionIds)jdbc.update("DELETE FROM game_sessions WHERE id=?",id);for(long id:roomIds)jdbc.update("DELETE FROM rooms WHERE id=?",id);for(long id:userIds)jdbc.update("DELETE FROM users WHERE id=?",id);}
 @Test void adminRoutesEnforceUnauthenticatedPlayerAndAdminMatrix()throws Exception{UserEntity player=user(Role.PLAYER),admin=user(Role.ADMIN);for(String path:List.of("/api/v1/admin/overview","/api/v1/admin/users","/api/v1/admin/rooms","/api/v1/admin/games")){mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).header(HttpHeaders.AUTHORIZATION,bearer(player))).andExpect(status().isForbidden());mvc.perform(get(path).header(HttpHeaders.AUTHORIZATION,bearer(admin))).andExpect(status().isOk());}}
 @Test void overviewAndUserQueriesAreGlobalSafeFilteredDefaultedAndSecretFree()throws Exception{long before=jdbc.queryForObject("SELECT COUNT(*) FROM users",Long.class);UserEntity admin=user(Role.ADMIN),player=user(Role.PLAYER);String token=bearer(admin);mvc.perform(get("/api/v1/admin/overview").header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isOk()).andExpect(jsonPath("$.totalUsers").value(before+2));mvc.perform(get("/api/v1/admin/users?search="+player.getUsername()+"&role=PLAYER&status=ACTIVE&size=1").header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isOk()).andExpect(jsonPath("$.items.length()").value(1)).andExpect(jsonPath("$.items[0].userId").value(player.getId())).andExpect(jsonPath("$.items[0].rating").value(1000)).andExpect(jsonPath("$.items[0].gamesRated").value(0)).andExpect(jsonPath("$.items[0].totalGames").value(0)).andExpect(jsonPath("$.items[0].totalHands").value(0)).andExpect(jsonPath("$.items[0].passwordHash").doesNotExist()).andExpect(jsonPath("$.items[0].refreshTokens").doesNotExist());mvc.perform(get("/api/v1/admin/users/"+player.getId()).header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isOk()).andExpect(jsonPath("$.passwordHash").doesNotExist()).andExpect(jsonPath("$.rating").value(1000));mvc.perform(get("/api/v1/admin/users/"+Long.MAX_VALUE).header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isNotFound());}
 @Test void roomListAndDetailReportParticipantsWithoutPrivatePassword()throws Exception{UserEntity admin=user(Role.ADMIN),player=user(Role.PLAYER),spectator=user(Role.PLAYER);RoomEntity room=room(admin,RoomType.PRIVATE);roomPlayers.saveAndFlush(new RoomPlayerEntity(room.getId(),player.getId(),1,RoomPlayerState.READY,1000));roomPlayers.saveAndFlush(new RoomPlayerEntity(room.getId(),spectator.getId(),null,RoomPlayerState.SPECTATING,0));String token=bearer(admin);mvc.perform(get("/api/v1/admin/rooms?search="+room.getName()+"&status=WAITING&roomType=PRIVATE").header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].roomId").value(room.getId())).andExpect(jsonPath("$.items[0].seatedPlayers").value(1)).andExpect(jsonPath("$.items[0].spectators").value(1)).andExpect(jsonPath("$.items[0].passwordHash").doesNotExist());mvc.perform(get("/api/v1/admin/rooms/"+room.getId()).header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isOk()).andExpect(jsonPath("$.participants.length()").value(2)).andExpect(jsonPath("$.passwordHash").doesNotExist());mvc.perform(get("/api/v1/admin/rooms/"+Long.MAX_VALUE).header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isNotFound());}
 @Test void gameQueriesExposeAuditSafeSessionParticipantsAndHands()throws Exception{UserEntity admin=user(Role.ADMIN),player=user(Role.PLAYER);RoomEntity room=room(admin,RoomType.PUBLIC);Instant start=Instant.parse("2026-08-29T01:00:00Z");GameSessionEntity session=sessions.saveAndFlush(new GameSessionEntity(room.getId(),GameSessionStatus.FINISHED,start,start.plusSeconds(120)));sessionIds.add(session.getId());PokerHandEntity hand=hands.saveAndFlush(new PokerHandEntity(session.getId(),1,1,1,2,50,100,start,start.plusSeconds(60),GamePhase.FINISHED,"AS,KD,2C",HandEndReason.SHOWDOWN));handPlayers.saveAndFlush(new HandPlayerEntity(hand.getId(),player.getId(),1,1000,1100,100,PokerPlayerState.ACTIVE,true,false,"QH,QS"));String token=bearer(admin);mvc.perform(get("/api/v1/admin/games?status=FINISHED&roomId="+room.getId()+"&userId="+player.getId()).header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].gameSessionId").value(session.getId())).andExpect(jsonPath("$.items[0].participantCount").value(1)).andExpect(jsonPath("$.items[0].handCount").value(1));mvc.perform(get("/api/v1/admin/games/"+session.getId()).header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isOk()).andExpect(jsonPath("$.participants[0].netChips").value(100)).andExpect(jsonPath("$.holeCards").doesNotExist());mvc.perform(get("/api/v1/admin/games/"+session.getId()+"/hands").header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].boardCards").value("AS,KD,2C")).andExpect(jsonPath("$.items[0].holeCards").doesNotExist());mvc.perform(get("/api/v1/admin/games/"+Long.MAX_VALUE).header(HttpHeaders.AUTHORIZATION,token)).andExpect(status().isNotFound());}
 private UserEntity user(Role role){String s=UUID.randomUUID().toString().replace("-","").substring(0,10);UserEntity user=users.saveAndFlush(new UserEntity("ad_"+s,"hash","ad_"+s+"@example.test",role,AccountStatus.ACTIVE,5000));userIds.add(user.getId());return user;}private RoomEntity room(UserEntity owner,RoomType type){RoomEntity room=rooms.saveAndFlush(new RoomEntity("admin-"+UUID.randomUUID(),owner.getId(),type,type==RoomType.PRIVATE?"private-hash":null,6,50,100,1000,RoomStatus.WAITING,Instant.now()));roomIds.add(room.getId());return room;}private String bearer(UserEntity user){return "Bearer "+jwt.createAccessToken(user);}
}
